code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Extend each interrupted horizontal 8-bar through its openings, using the
    # adjacent blank rows as connecting tracks. The top marker seeds the track.
    walls = [r for r,row in enumerate(g) if 8 in row and sum(v == 8 for v in row) >= w//2]
    if walls and all(sum(v == 8 for v in g[r]) >= w//2 for r in walls):
        start = next(((r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v == 2), None)
        if start and all(sum(v == 8 for v in g[r]) >= w//2 for r in walls):
            for i,r in enumerate(walls):
                holes = [c for c,v in enumerate(g[r]) if v == 0]
                for c in holes:
                    g[r][c] = 2
                if i == 0:
                    lo,hi=min([start[1]]+holes),max([start[1]]+holes)
                    rr = r-1
                    if rr >= start[0]:
                        for c in range(lo,hi+1):
                            if g[rr][c] == 0: g[rr][c] = 2
                if i+1 < len(walls):
                    nr=walls[i+1]
                    between=list(range(r+1,nr))
                    if not between: continue
                    if len(between) == 1:
                        rr=between[0]
                        lo,hi=min(holes),max(holes)
                        # A single track spans openings in the next bar.
                        nh=[c for c,v in enumerate(g[nr]) if v==0]
                        if len(holes)==2 and len(nh)==1:
                            lo,hi=0,w-1
                        else:
                            lo,hi=min(holes+nh),max(holes+nh)
                        for c in range(lo,hi+1):
                            if g[rr][c]==0: g[rr][c]=2
                    else:
                        for c in holes:
                            for rr in between:
                                if g[rr][c]==0: g[rr][c]=2
                        nh=[c for c,v in enumerate(g[nr]) if v==0]
                        for rr in between:
                            if nh:
                                for c in range(min(nh),max(nh)+1):
                                    if g[rr][c]==0: g[rr][c]=2
            # Continue the final set of apertures to the lower edge.
            if walls:
                for c,v in enumerate(g[walls[-1]]):
                    if v==2:
                        for rr in range(walls[-1]+1,h):
                            if g[rr][c]==0: g[rr][c]=2
            return g
    return g
'''
